{* Code generated by authfly/codegen from specs/widgets/notice.def.ts. DO NOT EDIT.
   Authfly notice on UI8Kit 3 primitives: check email, verified, link error, sign out (form). Props as xgen. *}
{import '../authfly/components.latte'}
{var $id = $p['id'] ?? ''}{var $l = $p['labels'] ?? []}{var $error = $p['error'] ?? ''}
{var $formError = $error ? $id . '-error' : null}
{var $lm = ['aria-labelledby' => ($p['landmarkLabel'] ?? '') ? null : $id . '-title', 'aria-label' => $p['landmarkLabel'] ?? null]}
{var $isError = ($p['tone'] ?? 'default') === 'error'}
{capture $c3}
{include iconBadge, $p['icon'] ?? 'mail-check', $isError ? 'destructive' : 'default'}
{capture $c1}{if $p['detail'] ?? ''}
{include text, '', 'text-sm font-semibold text-foreground', ['data-testid' => 'detail'], afEsc($p['detail'] ?? '')}
{/if}{/capture}
{include head, $id, $p['title'] ?? '', $p['text'] ?? '', 'center', $isError ? 'alert' : 'status', $c1}
{if ($p['action'] ?? 'link') === 'form'}
{capture $c2}{include hidden, 'csrf', $p['csrf'] ?? ''}
{include button, '', 'submit', afSkin('button', 'default', 'w-full'), ['data-testid' => 'submit'], afEsc($l['cta'] ?? '')}{/capture}
{include form, $p['actionUrl'] ?? '', 'w-full', ['data-testid' => 'authfly-form'], $c2}
{else}
{include button, $l['ctaHref'] ?? '', '', afSkin('button', 'default', 'w-full'), ['data-testid' => 'cta'], afEsc($l['cta'] ?? '')}
{/if}
{if $l['secondary'] ?? ''}
{include link, $l['secondaryHref'] ?? '', afSkin('link', 'text-sm'), 'secondary', $l['secondary'] ?? ''}
{/if}
{/capture}
{include card, afSkin('widgetCard', 'items-center text-center'), ['data-testid' => 'authfly-notice', 'data-tone' => $p['tone'] ?? 'default'] + $lm, $c3}
